import { CloudWatchClient, PutMetricDataCommand } from '@aws-sdk/client-cloudwatch';

const cloudwatch = new CloudWatchClient({ region: 'ap-south-1' });

async function recordMetric(name: string, value: number, unit: string) {
  await cloudwatch.send(new PutMetricDataCommand({
    Namespace: 'MyApp',   // groups your metrics
    MetricData: [{
      MetricName: name,
      Value: value,
      Unit: unit,
      Dimensions: [
        { Name: 'Environment', Value: process.env.NODE_ENV ?? 'production' },
        { Name: 'Service', Value: 'api' },
      ],
      Timestamp: new Date(),
    }],
  }));
}

// Usage in your Express app:
app.post('/checkout', async (req, res) => {
  const start = Date.now();
  try {
    await processOrder(req.body);
    await recordMetric('OrdersCompleted', 1, 'Count');
    await recordMetric('CheckoutLatency', Date.now() - start, 'Milliseconds');
    res.json({ success: true });
  } catch (err) {
    await recordMetric('OrdersFailed', 1, 'Count');
    throw err;
  }
});

